    var hex;
    try {
      hex = CryptoJS.enc.Base64.parse(text).toString(HEX);
    } catch (e) {
      fail('secretKey 不是合法的 base64url：' + e.message);
    }
    if (hex.length !== 64) {
      fail('secretKey 解码后是 ' + (hex.length / 2) + ' 字节，规范要求 32 字节（base64url 无填充）');
